			this.inbound[p] = [];
			this.inPath[p] = [];
			for (let i = 0; i < this.cols; i++) {
				this.outbound[p][i] = 'X';
				this.inbound[p][i] = 'X';
				this.inPath[p][i] = 0;
				this.openConnectors.push(p * this.cols + i);
			}
		}
	}

	update() {
		//when doContinue is false it could not find an open connector to build path from
		let doContinue = this.cursorConnect();
		let numContinue = 0;
		let _wG_1 = 0; while ((doContinue) && ++_wG_1 < 20000) {
			doContinue = this.cursorConnect();
			numContinue++;
			this.completedPaths++;
		}
		this.closeOutEnds();
		return numContinue;
	}

	getPathFrom(col, row, scalar) {
		//trace connections from this point until we hit dead end, edge or point already in path
		let continuePath = true;
		let iter = 0;
		let pathPts = [];
		let ptidx = [];
		let atc = col;
		let atr = row;
		let _wG_2 = 0; while ((continuePath && iter < 1000) && ++_wG_2 < 20000) {
			iter++;
			pathPts.push({
				x: atc * scalar,
				y: atr * scalar
			});
			this.inPath[atr][atc] = 1;
			let idx = atr * this.cols + atc;
			if (!ptidx.includes(idx)) {
				ptidx.push(idx);
			} else {
				continuePath = false;
			}
			let cd = this.outbound[atr][atc];
			let nextr = atr;
			let nextc = atc;
			switch (cd) {
				case 'N':
					nextr--;
					break;
				case 'S':
					nextr++;
					break;
				case 'E':
					nextc++;
					break;
				case 'W':
					nextc--;
					break;
				case 'X':
					//dead end
					continuePath = false;
					break;
			}
			if (nextr < 0 || nextc < 0) {
				continuePath = false;
			}
			if (nextr >= this.gridSize || nextc >= this.gridSize) {
				continuePath = false;
			}
			atr = nextr;
			atc = nextc;
		}
		return pathPts;
	}

