	identifyLoops() {
		//if path loops back to itself there wont be a dead end to start path from, so we need to id a start point for each loop 
		//start point saved to knownLoops will be upper-left-most point in path
		let loopsIdentified = 0;
		for (let p = 0; p < this.rows; p++) {
