		}

		this.cursorSegmentLength = 2 + floor(random(5));
		if (this.cursorStrategy == "FLATWAVE") {
			//creates a narrow one segment waveform
			this.cursorSegmentLength = 1;
			this.turnHistory[0] = 1;
			this.turnHistory[1] = 1;
		}
		if (this.cursorStrategy == "BOXER") {
			//tries to return to its origin to make a box shape
			this.cursorOrigin = this.cursory * this.cols + this.cursorx;
			this.cursorSegmentLength = 5 + floor(random(5));
		}
		let canContinue = true;
		let _wG_4 = 0; while ((canContinue) && ++_wG_4 < 20000) {
