	closeOutEnds() {
		//force dead ends to connect where possible
		let deads = this.deadEnds.length;
		if (deads < 1) {
			return;
		}
		let closedOut = false;
		let oin;
		let oout;
		let removeable = [];
		let cdir;
		for (let i = 0; i < deads; i++) {
			closedOut = false;
			let c = this.deadEnds[i];
			let crow = floor(c / this.cols);
			let ccol = c % this.cols;
			cdir = this.outbound[crow][ccol];
			if (this.validIP(ccol + 1, crow)) {
				oin = this.inbound[crow][ccol + 1];
				oout = this.outbound[crow][ccol + 1];
				if (oout == 'X' || oout == 'E' || oout == 'W' || oin == 'X') {
					//close hole
					this.makeConnection(ccol, crow, 'E', true);
					closedOut = true;
				}
			}
			if (!closedOut && this.validIP(ccol - 1, crow)) {
				oin = this.inbound[crow][ccol - 1];
				oout = this.outbound[crow][ccol - 1];
				if (oout == 'X' || oout == 'W' || oout == 'E' || oin == 'X') {
					this.makeConnection(ccol, crow, 'W', true);
					closedOut = true;
				}
			}
			if (!closedOut && this.validIP(ccol, crow + 1)) {
				oin = this.inbound[crow + 1][ccol];
				oout = this.outbound[crow + 1][ccol];
				if (oout == 'X' || oout == 'S' || oout == 'N' || oin == 'X') {
					this.makeConnection(ccol, crow, 'S', true);
					closedOut = true;
				}
			}
			if (!closedOut && this.validIP(ccol, crow - 1)) {
				oin = this.inbound[crow - 1][ccol];
				oout = this.outbound[crow - 1][ccol];
				if (oout == 'X' || oout == 'S' || oout == 'N' || oin == 'X') {
					this.makeConnection(ccol, crow, 'N', true);
					closedOut = true;
				}
			}
			if (closedOut) {
				removeable.push(c);
			}
		}
		for (let i = 0; i < removeable.length; i++) {
			var c = removeable[i];
			this.deadEnds.splice(this.deadEnds.indexOf(c), 1);
		}
	}

	indexInDir(indir) {
		//get index of location in direction (this is useful for comparison)
		switch (indir) {
			case 'N':
				if (this.validIP(this.cursorx, this.cursory - 1)) {
					return (this.cursory - 1) * this.cols + this.cursorx;
				}
				break;
			case 'S':
				if (this.validIP(this.cursorx, this.cursory + 1)) {
					return (this.cursory + 1) * this.cols + this.cursorx;
				}
				break;
			case 'E':
				if (this.validIP(this.cursorx + 1, this.cursory)) {
					return this.cursory * this.cols + this.cursorx + 1;
				}
				break;
			case 'W':
				if (this.validIP(this.cursorx - 1, this.cursory)) {
					return this.cursory * this.cols + this.cursorx - 1;
				}
				break;
		}
		return -1;
	}

	cursorTravel(indir) {
		//update cursor position
		switch (indir) {
			case 'N':
				if (this.validIP(this.cursorx, this.cursory - 1)) {
					this.cursory--;
					return true;
				}
				break;
			case 'S':
				if (this.validIP(this.cursorx, this.cursory + 1)) {
					this.cursory++;
					return true;
				}
				break;
			case 'E':
				if (this.validIP(this.cursorx + 1, this.cursory)) {
					this.cursorx++;
					return true;
				}
				break;
			case 'W':
				if (this.validIP(this.cursorx - 1, this.cursory)) {
					this.cursorx--;
					return true;
				}
				break;
		}
		return false;
	}

	cursorTurnRight() {
		switch (this.cursorDir) {
			case 'N':
				this.cursorDir = 'E';
				break;
			case 'S':
				this.cursorDir = 'W';
				break;
			case 'E':
				this.cursorDir = 'S';
				break;
			case 'W':
				this.cursorDir = 'N';
				break;
		}
	}
	cursorOpposite() {
		switch (this.cursorDir) {
			case 'N':
				this.cursorDir = 'S';
				break;
			case 'S':
				this.cursorDir = 'N';
				break;
			case 'E':
				this.cursorDir = 'W';
				break;
			case 'W':
				this.cursorDir = 'E';
				break;
		}
	}
	addTurnToHistory(turnDir) {
		//turnRight = 1, turnLeft = 2
		for (let i = 2; i > 0; i--) {
			this.turnHistory[i] = this.turnHistory[i - 1];
		}
		this.turnHistory[0] = turnDir;
	}

}

