	packCircles(mind, maxd) {
		let keepGoing = true;
		var iter = 0;
		let minr = mind * 0.5;
		let maxr = maxd * 0.5;
		let testingRad = maxr;
		let repeatingCollisions = 0;
		let _wG_5 = 0; while ((keepGoing && iter < 1000) && ++_wG_5 < 20000) {
			iter++;
			let rx = minr + random(this.w - mind);
			let ry = minr + random(this.h - mind);
			let colliding = this.collidesWithExisting(rx, ry, testingRad);
			if (!colliding) {
				this.circles_x.push(rx);
				this.circles_y.push(ry);
				this.circles_r.push(testingRad);
				repeatingCollisions = 0;
			} else {
				repeatingCollisions++;
				if (repeatingCollisions >= 12) {
					repeatingCollisions = 0;
					testingRad--;
					if (testingRad < minr) {
						keepGoing = false;
					}
				}

			}
		}
	}

	collidesWithExisting(px, py, rad) {
		for (let i = 0; i < this.circles_r.length; i++) {
			let dx = this.circles_x[i] - px;
			let dy = this.circles_y[i] - py;
			let distc = sqrt(dx * dx + dy * dy);
			if (distc < (this.circles_r[i] + rad)) {
				return true;
			}
		}
		return false;
	}

	flowerShape(npt, rad) {
		let angStep = TWO_PI / npt;
		let circumference = TWO_PI * rad;
		let secDiam = circumference / (npt - 1);
		for (let i = 0; i < npt; i++) {
			let ang = i * angStep;
			let ofv = p5.Vector.fromAngle(ang);
			ofv.setMag(rad);
			arc(ofv.x, ofv.y, secDiam, secDiam, ang - HALF_PI, ang + PI - HALF_PI);
		}
	}
	circleVerts(centerx, centery, npt, rad) {
		let verts = [];
		var angStep = TWO_PI / npt;
		for (let i = 0; i < npt; i++) {
			var ang = i * angStep;
			var ofv = p5.Vector.fromAngle(ang);
			ofv.setMag(rad);
			ofv.x += centerx;
			ofv.y += centery;
			verts.push(ofv);
		}
		verts.push(verts[0]);
		return verts;
	}
}

