function noiseDistortPoints(pathpts, nmult, offset = 0) {
	let distorted = [];
	for (let i = 0; i < pathpts.length; i++) {
		let thispt = pathpts[i];
		let px = thispt.x;
		let py = thispt.y;
		let opx = px + offset;
		let opy = py + offset;
		let noisevx = noise(opx * 0.06, opy * 0.06);
		let noisevy = noise((opx + 100) * 0.06, (opy + 100) * 0.06);
		noisevx = 1 - (noisevx * 2);
		noisevy = 1 - (noisevy * 2);
		distorted.push({
			x: px + (noisevx * nmult),
			y: py + (noisevy * nmult)
		});
	}

	return distorted;
}

function splineTo(points) {
	var nv = points.length;
	vertex(points[0].x, points[0].y);
	if (nv >= 3) {
		let p0, p1, p2;
		for (let i = 1, n = nv - 1; i <= n; i++) {
			p0 = points[i - 1];
			p1 = points[i];
			if (i == n) { // finish him
				//path.cubicTo(
				bezierVertex(
					(2 * p0.x + p1.x) / 3, (2 * p0.y + p1.y) / 3,
					(2 * p1.x + p0.x) / 3, (2 * p1.y + p0.y) / 3,
					p1.x, p1.y
				);
			} else {
				p2 = points[i + 1];
				//path.cubicTo(
				bezierVertex(
					(2 * p0.x + p1.x) / 3, (2 * p0.y + p1.y) / 3,
					(2 * p1.x + p0.x) / 3, (2 * p1.y + p0.y) / 3,
					(p0.x + 4 * p1.x + p2.x) / 6, (p0.y + 4 * p1.y + p2.y) / 6
				);
			}
		}
	}
}

function areRectanglesOverlapping(rect1, rect2) {
	// properties
	const [x1, y1, w1, h1] = [rect1.x, rect1.y, rect1.w, rect1.h];
	const [x2, y2, w2, h2] = [rect2.x, rect2.y, rect2.w, rect2.h];

	// for non-overlapping conditions
	if (x1 + w1 <= x2 || // rect1 is to the left of rect2
		x2 + w2 <= x1 || // rect2 is to the left of rect1
		y1 + h1 <= y2 || // rect1 is above rect2
		y2 + h2 <= y1) { // rect2 is above rect1
		return false; // overlap
	}

	return true; // detected
}
